from django.db import transaction
from rolap.api.models.rulesets.rulesets_db import DEFAULT_MEASURE


@transaction.atomic
def update_prediction_config(apps, schema_editor):
    Ruleset = apps.get_model('api', 'Ruleset')

    for ruleset in Ruleset.objects.all():
        if ruleset.voting_measure is None:
            dataset = ruleset.attached_to_dataset
            if dataset is None:
                print(f"Skipping ruleset ID={ruleset.id} as it is not attached to any dataset")  # noqa
                continue
            if dataset.project is None or dataset.project.type_of_problem == "survival":
                continue
            voting_measure = ruleset.generation_params.get(
                "algorithm_params", {}).get("voting_measure", DEFAULT_MEASURE)
            ruleset.voting_measure = voting_measure
            print(f"Updating voting measure of ruleset ID={ruleset.id} to '{voting_measure}'")  # noqa
            ruleset.save()


